public class Main {
    public static void main(String[] args) throws Exception {
        byte[] b;
        try (var in = Main.class.getResourceAsStream("Main.class")) {
            if (in == null) throw new IllegalStateException("cannot read own class file");
            b = in.readAllBytes();
        }
        String magic = String.format("%02X%02X%02X%02X", b[0], b[1], b[2], b[3]);
        int minor = ((b[4] & 0xff) << 8) | (b[5] & 0xff);
        int major = ((b[6] & 0xff) << 8) | (b[7] & 0xff);
        int cpCount = ((b[8] & 0xff) << 8) | (b[9] & 0xff);

        System.out.println("=== ClassFile header of Main.class ===");
        System.out.println("magic             : " + magic);
        System.out.println("magic == CAFEBABE : " + magic.equals("CAFEBABE"));
        System.out.println("minor_version     : " + minor);
        System.out.println("major_version     : " + major + "   (8=52, 11=55, 17=61, 21=65, 23=67)");
        System.out.println("constant_pool_count : " + cpCount + " (index starts at 1, so count = entries+1)");
        System.out.println("file size > 44 bytes (header is 10 fixed + ...) : " + (b.length > 44));
        System.out.println("=== implied by header ===");
        System.out.println("min JVM major required = " + major + " -> runs on JDK " + (major - 44) + "+");
    }
}
